1: <?php
2: /**
3:  * Núcleo de autenticação, sessão, permissões, CSRF e mensagens do EpiSafe.
4:  *
5:  * Todas as páginas incluem este arquivo (direto ou via layout.php).
6:  */
7: 
8: require_once __DIR__ . '/conexao.php';
9: 
10: date_default_timezone_set('America/Sao_Paulo');
11: 
12: /* -------------------------------------------------------------------------
13:  * Sessão
14:  * ---------------------------------------------------------------------- */
15: 
16: function sessao_iniciar(): void
17: {
18:     if (session_status() === PHP_SESSION_ACTIVE) {
19:         return;
20:     }
21: 
22:     $https = (!empty($_SERVER['HTTPS']) && strtolower((string)$_SERVER['HTTPS']) !== 'off');
23: 
24:     session_set_cookie_params([
25:         'lifetime' => 0,
26:         'path'     => '/',
27:         'httponly' => true,
28:         'secure'   => $https,
29:         'samesite' => 'Lax',
30:     ]);
31: 
32:     session_name('EPISAFE_SESSID');
33:     session_start();
34: }
35: 
36: sessao_iniciar();
37: 
38: /* -------------------------------------------------------------------------
39:  * Saída segura
40:  * ---------------------------------------------------------------------- */
41: 
42: function h($valor): string
43: {
44:     return htmlspecialchars((string)($valor ?? ''), ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
45: }
46: 
47: /* -------------------------------------------------------------------------
48:  * Perfis de acesso
49:  * ---------------------------------------------------------------------- */
50: 
51: function perfis_validos(): array
52: {
53:     return ['Administrador', 'Gestor', 'Almoxarifado', 'Tecnico'];
54: }
55: 
56: /**
57:  * Converte qualquer variação gravada no banco (antiga ou nova) em um dos
58:  * perfis canônicos: Administrador, Gestor, Almoxarifado ou Tecnico.
59:  */
60: function normalizar_perfil(?string $valor): string
61: {
62:     $v = mb_strtolower(trim((string)$valor));
63: 
64:     return match (true) {
65:         in_array($v, ['administrador', 'admin', 'adm'], true) => 'Administrador',
66:         in_array($v, ['gestor', 'gerente'], true)             => 'Gestor',
67:         in_array($v, ['almoxarifado', 'almoxarife'], true)    => 'Almoxarifado',
68:         default                                               => 'Tecnico',
69:     };
70: }
71: 
72: function rotulo_perfil(?string $perfil): string
73: {
74:     return match (normalizar_perfil($perfil)) {
75:         'Administrador' => 'Administrador',
76:         'Gestor'        => 'Gestor',
77:         'Almoxarifado'  => 'Almoxarifado',
78:         default         => 'Técnico',
79:     };
80: }
81: 
82: /** Classe CSS usada no "chip" de perfil. */
83: function classe_perfil(?string $perfil): string
84: {
85:     return 'perfil-' . mb_strtolower(normalizar_perfil($perfil));
86: }
87: 
88: function status_ativo(?string $status): bool
89: {
90:     return mb_strtolower(trim((string)$status)) === 'ativo';
91: }
92: 
93: /* -------------------------------------------------------------------------
94:  * Dados do usuário logado
95:  * ---------------------------------------------------------------------- */
96: 
97: function usuario_logado(): bool
98: {
99:     return !empty($_SESSION['usuario_id']);
100: }
101: 
102: function usuario_id(): int
103: {
104:     return (int)($_SESSION['usuario_id'] ?? 0);
105: }
106: 
107: function perfil_atual(): string
108: {
109:     return normalizar_perfil(
110:         $_SESSION['usuario_perfil']
111:         ?? $_SESSION['perfil']
112:         ?? $_SESSION['usuario_funcao']
113:         ?? null
114:     );
115: }
116: 
117: function usuario_atual(): array
118: {
119:     return [
120:         'id'     => usuario_id(),
121:         'nome'   => (string)($_SESSION['usuario_nome'] ?? 'Usuário'),
122:         'email'  => (string)($_SESSION['usuario_email'] ?? ''),
123:         'perfil' => perfil_atual(),
124:         'setor'  => (string)($_SESSION['usuario_setor'] ?? ''),
125:     ];
126: }
127: 
128: function e_admin(): bool
129: {
130:     return perfil_atual() === 'Administrador';
131: }
132: 
133: /* -------------------------------------------------------------------------
134:  * Redirecionamento e proteção de páginas
135:  * ---------------------------------------------------------------------- */
136: 
137: function redirecionar(string $destino): void
138: {
139:     header('Location: ' . $destino);
140:     exit;
141: }
142: 
143: /**
144:  * Garante que exista uma sessão válida e que o usuário ainda esteja ativo no
145:  * banco (se o administrador desativar a conta, o acesso cai na hora).
146:  */
147: function exigir_login(): void
148: {
149:     if (!usuario_logado()) {
150:         flash('aviso', 'Faça login para continuar.');
151:         redirecionar('index.php?aviso=login');
152:     }
153: 
154:     static $validado = false;
155: 
156:     if ($validado) {
157:         return;
158:     }
159: 
160:     global $pdo;
161: 
162:     try {
163:         $stmt = $pdo->prepare(
164:             "SELECT id, nome, email, tipo_acesso, funcao, setor, status
165:                FROM usuarios
166:               WHERE id = ?
167:               LIMIT 1"
168:         );
169:         $stmt->execute([usuario_id()]);
170:         $u = $stmt->fetch();
171:     } catch (Throwable $e) {
172:         error_log('Falha ao validar sessão: ' . $e->getMessage());
173:         $u = null;
174:     }
175: 
176:     if (!$u || !status_ativo($u['status'] ?? 'Ativo')) {
177:         encerrar_sessao();
178:         flash('erro', 'Sua sessão expirou ou a conta foi desativada. Entre novamente.');
179:         redirecionar('index.php?aviso=sessao');
180:     }
181: 
182:     // Mantém a sessão sincronizada com o banco.
183:     $_SESSION['usuario_nome']   = $u['nome'];
184:     $_SESSION['usuario_email']  = $u['email'];
185:     $_SESSION['usuario_setor']  = $u['setor'] ?? '';
186:     $_SESSION['usuario_perfil'] = normalizar_perfil($u['tipo_acesso'] ?? $u['funcao'] ?? null);
187:     $_SESSION['usuario_funcao'] = $u['funcao'] ?? $_SESSION['usuario_perfil'];
188:     $_SESSION['perfil']         = $_SESSION['usuario_perfil'];
189: 
190:     $validado = true;
191: }
192: 
193: function exigir_perfil(array $perfisPermitidos): void
194: {
195:     exigir_login();
196: 
197:     $permitidos = array_map('normalizar_perfil', $perfisPermitidos);
198: 
199:     if (!in_array(perfil_atual(), $permitidos, true)) {
200:         http_response_code(403);
201:         flash('erro', 'Você não tem permissão para acessar essa página.');
202:         redirecionar('dashboard_admin.php');
203:     }
204: }
205: 
206: /* -------------------------------------------------------------------------
207:  * CSRF
208:  * ---------------------------------------------------------------------- */
209: 
210: function csrf_token(): string
211: {
212:     if (empty($_SESSION['csrf_token'])) {
213:         $_SESSION['csrf_token'] = bin2hex(random_bytes(32));
214:     }
215: 
216:     return $_SESSION['csrf_token'];
217: }
218: 
219: function csrf_campo(): string
220: {
221:     return '<input type="hidden" name="csrf_token" value="' . h(csrf_token()) . '">';
222: }
223: 
224: function csrf_validar(): bool
225: {
226:     $enviado = $_POST['csrf_token'] ?? '';
227: 
228:     return is_string($enviado)
229:         && $enviado !== ''
230:         && hash_equals(csrf_token(), $enviado);
231: }
232: 
233: /**
234:  * Deve ser chamado no início de qualquer página que processe POST.
235:  * Em caso de token inválido, avisa e devolve o usuário para a mesma tela.
236:  */
237: function csrf_proteger(): void
238: {
239:     if ($_SERVER['REQUEST_METHOD'] !== 'POST') {
240:         return;
241:     }
242: 
243:     if (!csrf_validar()) {
244:         flash('erro', 'Sessão expirada. Envie o formulário novamente.');
245:         redirecionar(basename($_SERVER['PHP_SELF'] ?? 'index.php'));
246:     }
247: }
248: 
249: /* -------------------------------------------------------------------------
250:  * Mensagens (flash)
251:  * ---------------------------------------------------------------------- */
252: 
253: function flash(string $tipo, string $mensagem): void
254: {
255:     $_SESSION['flash'][] = ['tipo' => $tipo, 'mensagem' => $mensagem];
256: }
257: 
258: function consumir_flashes(): array
259: {
260:     $mensagens = $_SESSION['flash'] ?? [];
261:     unset($_SESSION['flash']);
262: 
263:     return $mensagens;
264: }
265: 
266: /* -------------------------------------------------------------------------
267:  * Login
268:  * ---------------------------------------------------------------------- */
269: 
270: function ip_do_usuario(): string
271: {
272:     return substr((string)($_SERVER['REMOTE_ADDR'] ?? ''), 0, 45);
273: }
274: 
275: /** Segundos restantes de bloqueio por excesso de tentativas (0 = liberado). */
276: function login_bloqueado_por(): int
277: {
278:     $ate = (int)($_SESSION['login_bloqueado_ate'] ?? 0);
279: 
280:     return max(0, $ate - time());
281: }
282: 
283: function registrar_falha_login(): void
284: {
285:     $falhas = (int)($_SESSION['login_falhas'] ?? 0) + 1;
286:     $_SESSION['login_falhas'] = $falhas;
287: 
288:     if ($falhas >= 5) {
289:         $_SESSION['login_bloqueado_ate'] = time() + 300; // 5 minutos
290:         $_SESSION['login_falhas'] = 0;
291:     }
292: }
293: 
294: function limpar_falhas_login(): void
295: {
296:     unset($_SESSION['login_falhas'], $_SESSION['login_bloqueado_ate']);
297: }
298: 
299: /**
300:  * Valida as credenciais e cria a sessão.
301:  *
302:  * @return array{0: bool, 1: string} [sucesso, mensagem de erro]
303:  */
304: function autenticar(string $email, string $senha): array
305: {
306:     global $pdo;
307: 
308:     $stmt = $pdo->prepare("SELECT * FROM usuarios WHERE email = ? LIMIT 1");
309:     $stmt->execute([$email]);
310:     $u = $stmt->fetch();
311: 
312:     if (!$u || !password_verify($senha, (string)$u['senha'])) {
313:         registrar_falha_login();
314: 
315:         return [false, 'E-mail ou senha inválidos.'];
316:     }
317: 
318:     if (!status_ativo($u['status'] ?? 'Ativo')) {
319:         return [false, 'Sua conta está desativada. Procure o administrador.'];
320:     }
321: 
322:     // Atualiza o hash caso o algoritmo padrão do PHP tenha mudado.
323:     if (password_needs_rehash((string)$u['senha'], PASSWORD_DEFAULT)) {
324:         try {
325:             $up = $pdo->prepare("UPDATE usuarios SET senha = ? WHERE id = ?");
326:             $up->execute([password_hash($senha, PASSWORD_DEFAULT), $u['id']]);
327:         } catch (Throwable $e) {
328:             error_log('Falha ao atualizar hash de senha: ' . $e->getMessage());
329:         }
330:     }
331: 
332:     $perfil = normalizar_perfil($u['tipo_acesso'] ?? $u['funcao'] ?? null);
333: 
334:     session_regenerate_id(true);
335:     limpar_falhas_login();
336: 
337:     $_SESSION['usuario_id']     = (int)$u['id'];
338:     $_SESSION['usuario_nome']   = $u['nome'];
339:     $_SESSION['usuario_email']  = $u['email'];
340:     $_SESSION['usuario_setor']  = $u['setor'] ?? '';
341:     $_SESSION['usuario_perfil'] = $perfil;
342:     $_SESSION['usuario_funcao'] = $u['funcao'] ?? $perfil;
343:     $_SESSION['perfil']         = $perfil;
344:     $_SESSION['ultimo_login']   = $u['ultimo_acesso'] ?? null;
345: 
346:     // Guarda o último acesso (data/hora/IP) para exibir no perfil.
347:     try {
348:         $up = $pdo->prepare(
349:             "UPDATE usuarios
350:                 SET ultimo_acesso = NOW(), ultimo_ip = ?
351:               WHERE id = ?"
352:         );
353:         $up->execute([ip_do_usuario(), (int)$u['id']]);
354:     } catch (Throwable $e) {
355:         error_log('Falha ao registrar último acesso: ' . $e->getMessage());
356:     }
357: 
358:     return [true, ''];
359: }
360: 
361: function encerrar_sessao(): void
362: {
363:     $_SESSION = [];
364: 
365:     if (ini_get('session.use_cookies')) {
366:         $params = session_get_cookie_params();
367:         setcookie(
368:             session_name(),
369:             '',
370:             [
371:                 'expires'  => time() - 42000,
372:                 'path'     => $params['path'],
373:                 'domain'   => $params['domain'],
374:                 'secure'   => (bool)$params['secure'],
375:                 'httponly' => (bool)$params['httponly'],
376:                 'samesite' => $params['samesite'] ?? 'Lax',
377:             ]
378:         );
379:     }
380: 
381:     session_destroy();
382: }
383: 
384: /* -------------------------------------------------------------------------
385:  * Utilidades de data
386:  * ---------------------------------------------------------------------- */
387: 
388: function data_br(?string $data, bool $comHora = false): string
389: {
390:     if (empty($data) || $data === '0000-00-00' || $data === '0000-00-00 00:00:00') {
391:         return '—';
392:     }
393: 
394:     $ts = strtotime($data);
395: 
396:     if ($ts === false) {
397:         return '—';
398:     }
399: 
400:     return date($comHora ? 'd/m/Y H:i' : 'd/m/Y', $ts);
401: }

