361: .user-dropdown-head{display:flex;flex-direction:column;gap:3px;padding:12px 12px 13px;border-bottom:1px solid var(--linha);margin-bottom:6px}
362: .user-dropdown-head strong{font-size:14.5px;line-height:1.3}
363: .user-dropdown-head span{font-size:12.5px;color:var(--suave);overflow:hidden;text-overflow:ellipsis}
364: .user-dropdown-head .chip{margin-top:6px;align-self:flex-start}
365: 
366: .user-dropdown a,.logout-link{
367:     display:flex;align-items:center;gap:10px;
368:     width:100%;padding:9px 12px;border-radius:var(--raio-sm);
369:     color:var(--tinta-2);font-size:14px;font-weight:500;
370:     text-decoration:none;background:none;border:0;cursor:pointer;font-family:inherit;text-align:left;
371: }
372: .user-dropdown a:hover,.logout-link:hover{background:var(--marca-50);color:var(--marca-700)}
373: .logout-form{margin:0;border-top:1px solid var(--linha);padding-top:6px;margin-top:6px}
374: .logout-link{color:var(--vermelho)}
375: .logout-link:hover{background:var(--vermelho-bg);color:var(--vermelho)}
376: 
377: /* ---------- Menu ---------- */
378: .menu{
379:     position:sticky;top:0;z-index:30;
380:     background:var(--branco);border-bottom:1px solid var(--linha-forte);
381:     box-shadow:0 6px 14px -12px rgba(29,33,39,.4);
382: }
383: .menu-inner{
384:     max-width:var(--largura);margin:0 auto;padding:0 22px;
385:     display:flex;overflow-x:auto;scrollbar-width:thin;
386: }
387: .nav-group{display:flex;flex:none}
388: .nav-group + .nav-group{margin-left:8px;padding-left:8px;border-left:1px solid var(--linha)}
389: 
390: .nav-link{
391:     display:flex;align-items:center;gap:8px;white-space:nowrap;
392:     padding:14px 12px 11px;
393:     border-bottom:3px solid transparent;
394:     color:var(--suave);text-decoration:none;font-weight:500;font-size:14.5px;
395:     transition:background-color .15s,color .15s,border-color .15s;
396: }
397: .nav-link:hover{color:var(--marca-900);background:var(--marca-50)}
398: .nav-link.ativo{color:var(--marca-700);border-bottom-color:var(--marca-500);font-weight:700}
399: .nav-link:focus-visible{outline:3px solid var(--marca-600);outline-offset:-3px}
400: .nav-icon{display:inline-flex;flex:none}
401: 
402: /* ---------- Conteúdo ---------- */
403: .main-content{
404:     flex:1;width:100%;max-width:var(--largura);
405:     margin:0 auto;padding:28px 28px 52px;min-width:0;
406: }
407: 
408: .page-heading{
409:     display:flex;align-items:center;justify-content:space-between;gap:20px;
410:     flex-wrap:wrap;margin-bottom:24px;
411: }
412: .page-heading-main{display:flex;align-items:center;gap:16px;min-width:0}
413: .page-badge{
414:     display:grid;place-items:center;flex:none;
415:     width:52px;height:52px;border-radius:14px;
416:     background:var(--marca-500);color:var(--marca-900);
417:     box-shadow:0 0 0 4px var(--marca-100);
418: }
419: .page-heading h1{
420:     margin:0;font-family:var(--fonte-titulo);font-weight:700;
421:     font-size:29px;line-height:1.15;letter-spacing:-.02em;color:var(--marca-900);
422: }
423: .page-heading p{margin:3px 0 0;color:var(--suave);font-size:15px;max-width:75ch}
424: .page-heading-actions{display:flex;gap:10px;flex-wrap:wrap}
425: 
426: /* ---------- Indicadores ---------- */
427: .stats-grid{
428:     display:grid;gap:16px;margin-bottom:24px;
429:     grid-template-columns:repeat(auto-fit,minmax(215px,1fr));
430: }
431: .stat-card{
432:     --c:var(--marca-700);
433:     --cbg:var(--marca-50);
434:     position:relative;display:flex;flex-direction:column;gap:2px;
435:     padding:18px 20px 18px;
436:     background:var(--branco);border:1px solid var(--linha);border-radius:var(--raio);
437:     box-shadow:var(--sombra);overflow:hidden;
438: }
439: .stat-card::before{
440:     content:"";position:absolute;left:0;top:0;bottom:0;width:4px;background:var(--c);
441: }
442: .stat-top{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}
443: .stat-card span.stat-label{
444:     display:flex;align-items:center;
445:     color:var(--suave);font-size:13.5px;font-weight:600;
446:     text-transform:uppercase;letter-spacing:.04em;
447: }
448: .stat-icon{
449:     display:grid;place-items:center;flex:none;
450:     width:38px;height:38px;border-radius:10px;
451:     background:var(--cbg);color:var(--c);
452: }
453: .stat-card strong{
454:     font-family:var(--fonte-titulo);font-weight:700;font-variant-numeric:tabular-nums;
455:     font-size:36px;line-height:1.15;letter-spacing:-.02em;color:var(--tinta);
456:     margin-top:8px;
457: }
458: .stat-card small{color:var(--suave);font-size:13px}
459: .stat-card small b{color:var(--c)}
460: .stat-card.orange{--c:var(--laranja);--cbg:var(--laranja-bg)}
461: .stat-card.blue{--c:var(--marca-700);--cbg:var(--marca-50)}
462: .stat-card.green{--c:var(--verde);--cbg:var(--verde-bg)}
463: .stat-card.red{--c:var(--vermelho);--cbg:var(--vermelho-bg)}
464: .stat-card.yellow{--c:var(--amarelo);--cbg:var(--amarelo-bg)}
465: .stat-card.pale{--c:#64748b;--cbg:#eef1f5}
466: 
467: /* Ações rápidas */
468: .quick-grid{display:grid;gap:12px;grid-template-columns:repeat(auto-fit,minmax(190px,1fr))}
469: .quick-card{
470:     display:flex;align-items:center;gap:13px;
471:     padding:15px 16px;background:#fff;border:1px solid var(--linha);border-radius:var(--raio);
472:     color:var(--tinta);text-decoration:none;
473:     transition:border-color .15s,box-shadow .15s,transform .15s;
474: }
475: .quick-card:hover{border-color:var(--marca-500);box-shadow:var(--sombra);transform:translateY(-1px)}
476: .quick-card .stat-icon{width:40px;height:40px}
477: .quick-card strong{display:block;font-size:14.5px;line-height:1.3}
478: .quick-card small{color:var(--suave);font-size:12.5px}
479: 
480: /* ---------- Painéis ---------- */
481: .content-card{
482:     background:var(--branco);border:1px solid var(--linha);
483:     border-radius:var(--raio);padding:22px 24px 24px;margin-bottom:22px;
484:     box-shadow:var(--sombra);
485: }
486: .content-card h2{
487:     margin:0;font-family:var(--fonte-titulo);font-weight:700;
488:     font-size:19px;letter-spacing:-.01em;color:var(--marca-900);
489: }
490: .card-heading{
491:     display:flex;align-items:flex-start;justify-content:space-between;gap:16px;flex-wrap:wrap;
492:     margin-bottom:16px;padding-bottom:14px;border-bottom:1px solid var(--linha);
493: }
494: .card-heading h2{margin:0}
495: .card-sub{margin:3px 0 0;color:var(--suave);font-size:13.5px}
496: .card-heading-actions{display:flex;align-items:center;gap:10px;flex-wrap:wrap}
497: 
498: /* ---------- Formulários ---------- */
499: .form-grid{
500:     display:grid;gap:16px 18px;
501:     grid-template-columns:repeat(auto-fit,minmax(210px,1fr));
502:     align-items:end;
503: }
504: .form-grid .campo-largo{grid-column:1/-1}
505: .form-grid label{display:block;margin-bottom:6px;font-size:13.5px;font-weight:600;color:var(--tinta)}
506: .form-grid label .obrigatorio{color:var(--vermelho);margin-left:2px}
507: .form-grid input,.form-grid select,.form-grid textarea{
508:     width:100%;padding:10px 12px;
509:     font:inherit;color:var(--tinta);
510:     background:#fff;border:1px solid #b9c4d0;border-radius:var(--raio-sm);
511:     transition:border-color .15s,box-shadow .15s;
512: }
513: .form-grid input[readonly]{background:#f5f7f9;color:var(--suave)}
514: .form-grid textarea{min-height:92px;resize:vertical}
515: .form-grid input::placeholder{color:#8a97a6}
516: .form-grid input:focus,.form-grid select:focus,.form-grid textarea:focus{
517:     outline:none;border-color:var(--marca-600);
518:     box-shadow:0 0 0 3px rgba(245,168,0,.28);
519: }
520: .form-action{display:flex;align-items:flex-end;gap:10px}
521: .form-actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:18px;padding-top:16px;border-top:1px solid var(--linha)}
522: .ajuda{margin:5px 0 0;font-size:12.5px;color:var(--suave-2)}
523: .campo-senha{position:relative}
524: .campo-senha input{padding-right:44px}
525: .ver-senha{
526:     position:absolute;right:6px;top:50%;transform:translateY(-50%);
527:     display:grid;place-items:center;width:32px;height:32px;
528:     background:none;border:0;border-radius:var(--raio-sm);color:var(--suave);cursor:pointer;
529: }
530: .ver-senha:hover{background:var(--marca-50);color:var(--marca-700)}
531: 
532: /* ---------- Botões ---------- */
533: .botao{
534:     display:inline-flex;align-items:center;justify-content:center;gap:8px;
535:     padding:10px 18px;font:inherit;font-weight:600;font-size:14.5px;line-height:1.2;
536:     color:var(--marca-900);background:var(--marca-500);
537:     border:1px solid var(--marca-500);border-radius:var(--raio-sm);cursor:pointer;text-decoration:none;
538:     transition:background-color .15s,border-color .15s,color .15s,transform .05s;
539:     white-space:nowrap;
540: }
541: .botao:hover{background:var(--marca-600);border-color:var(--marca-600)}
542: .botao:active{transform:translateY(1px)}
543: .botao:focus-visible{outline:3px solid var(--marca-100);outline-offset:2px;box-shadow:0 0 0 2px var(--marca-900)}
544: .botao-sm{padding:6px 11px;font-size:13px;gap:6px}
545: .botao-sec{background:#fff;color:var(--marca-700);border-color:var(--linha-forte)}
546: .botao-sec:hover{background:var(--marca-50);border-color:var(--marca-500);color:var(--marca-900)}
547: .botao-perigo{background:#fff;color:var(--vermelho);border-color:#e3aaa5}
548: .botao-perigo:hover{background:var(--vermelho-bg);border-color:var(--vermelho);color:var(--vermelho)}
549: .botao-sucesso{background:var(--verde);border-color:var(--verde)}
550: .botao-sucesso:hover{background:#17653f;border-color:#17653f}
551: .botao-ghost{background:transparent;border-color:transparent;color:var(--marca-700);padding:6px 8px}
552: .botao-ghost:hover{background:var(--marca-50)}
553: .botao[disabled]{opacity:.55;cursor:not-allowed}
554: 
555: /* ---------- Alertas ---------- */
556: .alerta{
557:     display:flex;align-items:flex-start;gap:11px;
558:     margin:0 0 20px;padding:13px 15px;border-radius:var(--raio-sm);
559:     border:1px solid;border-left-width:5px;font-weight:500;font-size:14.5px;
560:     animation:fadein .2s ease-out;
561: }
562: @keyframes fadein{from{opacity:0;transform:translateY(-3px)}to{opacity:1;transform:none}}
563: .alerta-icon{margin-top:1px}
564: .alerta > span:nth-child(2){flex:1;min-width:0}
565: .alerta-fechar{
566:     display:grid;place-items:center;flex:none;width:26px;height:26px;
567:     background:none;border:0;border-radius:4px;color:inherit;cursor:pointer;opacity:.75;
568: }
569: .alerta-fechar:hover{opacity:1;background:rgba(0,0,0,.07)}
570: .alerta.sucesso{background:var(--verde-bg);color:#17653f;border-color:#a9d6bf;border-left-color:var(--verde)}
571: .alerta.erro{background:var(--vermelho-bg);color:#8f241d;border-color:#ebb9b4;border-left-color:var(--vermelho)}
572: .alerta.aviso{background:var(--amarelo-bg);color:#6b4a00;border-color:#e8d28c;border-left-color:#d6a500}
573: .alerta.info{background:var(--marca-50);color:#6b4a00;border-color:#f0d79a;border-left-color:var(--marca-500)}
574: 
575: /* ---------- Ferramentas da tabela ---------- */
576: .table-tools{
577:     display:flex;align-items:center;gap:10px;flex-wrap:wrap;
578:     margin-bottom:14px;
579: }
580: .search-box{
581:     position:relative;display:flex;align-items:center;flex:1 1 260px;max-width:380px;
582: }
583: .search-box svg{position:absolute;left:12px;color:var(--suave-2);pointer-events:none}
584: .search-box input{
585:     width:100%;padding:9px 12px 9px 38px;
586:     font:inherit;font-size:14px;color:var(--tinta);
587:     background:#fff;border:1px solid #b9c4d0;border-radius:var(--raio-sm);
588: }
589: .search-box input:focus{outline:none;border-color:var(--marca-600);box-shadow:0 0 0 3px rgba(245,168,0,.28)}
590: .table-filter{
591:     padding:9px 12px;font:inherit;font-size:14px;color:var(--tinta);
592:     background:#fff;border:1px solid #b9c4d0;border-radius:var(--raio-sm);cursor:pointer;
593: }
594: .table-filter:focus{outline:none;border-color:var(--marca-600);box-shadow:0 0 0 3px rgba(245,168,0,.28)}
595: .table-count{
596:     margin-left:auto;padding:5px 11px;border-radius:20px;
597:     background:var(--marca-50);border:1px solid var(--marca-100);
598:     color:var(--marca-700);font-size:12.5px;font-weight:600;white-space:nowrap;
599: }
600: 
601: /* ---------- Tabelas ---------- */
602: .table-wrap{
603:     position:relative;overflow:auto;max-height:70vh;
604:     background:var(--branco);border:1px solid var(--linha-forte);border-radius:var(--raio);
605: }
606: .table-wrap table{
607:     width:100%;border-collapse:separate;border-spacing:0;
608:     font-size:14px;font-variant-numeric:tabular-nums;
609: }
610: .table-wrap th{
611:     position:sticky;top:0;z-index:2;
612:     padding:12px 16px;text-align:left;white-space:nowrap;
613:     font-size:12.5px;font-weight:700;letter-spacing:.05em;text-transform:uppercase;
614:     color:#f7f3ea;background:var(--marca-900);
615:     border-bottom:1px solid var(--marca-900);
616: }
617: .table-wrap th[data-sort]{cursor:pointer;user-select:none;padding-right:28px;position:sticky}
618: .table-wrap th[data-sort]::after{
619:     content:"↕";position:absolute;right:12px;opacity:.45;font-size:11px;
620: }
621: .table-wrap th[data-sort][aria-sort="ascending"]::after{content:"↑";opacity:1}
622: .table-wrap th[data-sort][aria-sort="descending"]::after{content:"↓";opacity:1}
623: .table-wrap th[data-sort]:hover{background:var(--marca-800)}
624: .table-wrap th:first-child,.table-wrap td:first-child{padding-left:20px}
625: .table-wrap th:last-child,.table-wrap td:last-child{padding-right:20px}
626: 
627: .table-wrap td{
628:     padding:11px 16px;vertical-align:middle;color:var(--tinta);
629:     border-bottom:1px solid #e6ebf0;
630: }
631: .table-wrap tbody tr:nth-child(even) td{background:#fbf9f4}
632: .table-wrap tbody tr:hover td{background:var(--marca-50)}
633: .table-wrap tbody tr:last-child td{border-bottom:0}
634: .table-wrap tbody tr[hidden]{display:none}
635: 
636: .table-wrap th.num,.table-wrap td.num{text-align:right}
637: .table-wrap th.center,.table-wrap td.center{text-align:center}
638: 
639: .table-wrap td[colspan]{padding:38px 16px;text-align:center;color:var(--suave);font-weight:400;white-space:normal}
640: .table-wrap td a:not(.botao){color:var(--marca-600);font-weight:600;text-decoration:none}
641: .table-wrap td a:not(.botao):hover{text-decoration:underline}
642: 
643: .table-wrap tfoot td{
644:     position:sticky;bottom:0;
645:     font-weight:700;background:var(--marca-50);border-top:2px solid var(--linha-forte);
646: }
647: 
648: /* Células especiais */
649: .cell-user{display:flex;align-items:center;gap:11px;min-width:180px}
650: .cell-user .avatar{width:34px;height:34px;font-size:13px;background:var(--marca-100);color:var(--marca-700)}
651: .cell-user strong{display:block;font-size:14px;font-weight:600;line-height:1.3}
652: .cell-user small{display:block;color:var(--suave);font-size:12.5px;line-height:1.3}
653: .cell-mono{font-family:ui-monospace,SFMono-Regular,Consolas,monospace;font-size:12.5px;color:var(--tinta-2)}
654: .cell-muted{color:var(--suave-2);font-size:13px}
655: 
656: .acoes{display:flex;align-items:center;gap:5px;white-space:nowrap}
657: .acoes form{margin:0}
658: .acoes .botao{padding:5px 10px;font-size:12.5px}
659: .acoes .botao-ghost{padding:6px}
660: 
661: /* ---------- Chips / status ---------- */
662: .chip{
663:     display:inline-flex;align-items:center;gap:6px;
664:     padding:3px 9px;border-radius:3px;
665:     font-size:12px;font-weight:700;white-space:nowrap;letter-spacing:.01em;
666: }
667: .chip::before{content:"";width:6px;height:6px;border-radius:50%;background:currentColor}
668: 
669: .status{display:inline-flex;align-items:center;gap:6px;padding:3px 9px;border-radius:3px;font-size:12.5px;font-weight:700;white-space:nowrap}
670: .status::before{content:"";width:6px;height:6px;border-radius:50%;background:currentColor}
671: .status-ok{background:var(--verde-bg);color:#17653f}
672: .status-aviso{background:var(--amarelo-bg);color:#6b4a00}
673: .status-alerta{background:var(--vermelho-bg);color:#8f241d}
674: .status-neutro{background:#e9edf1;color:#445162}
675: .status-info{background:var(--marca-50);color:var(--marca-700)}
676: 
677: .perfil-administrador{background:#e7e4fb;color:#4a3a9e}
678: .perfil-gestor{background:var(--marca-50);color:var(--marca-700)}
679: .perfil-almoxarifado{background:var(--laranja-bg);color:#8a4707}
680: .perfil-tecnico{background:#e9edf1;color:#445162}
681: 
682: /* ---------- Barra de progresso ---------- */
683: .barra{display:flex;align-items:center;gap:9px;min-width:120px}
684: .barra-trilho{flex:1;height:7px;border-radius:20px;background:#e7ecf1;overflow:hidden}
685: .barra-trilho > span{display:block;height:100%;border-radius:20px;background:var(--verde)}
686: .barra-trilho > span.baixo{background:var(--amarelo)}
687: .barra-trilho > span.zerado{background:var(--vermelho)}
688: .barra-valor{font-size:12.5px;font-weight:700;font-variant-numeric:tabular-nums;min-width:52px;text-align:right}
689: 
690: /* ---------- Perfil ---------- */
691: .profile-hero{
692:     display:flex;align-items:center;gap:22px;flex-wrap:wrap;
693:     padding:26px 28px;margin-bottom:22px;
694:     background:
695:         radial-gradient(120% 160% at 100% 0%,rgba(245,168,0,.22),transparent 55%),
696:         linear-gradient(120deg,var(--marca-900),var(--marca-800));
697:     border-radius:var(--raio);color:#fff;box-shadow:var(--sombra);
698: }
699: .profile-avatar{
700:     display:grid;place-items:center;flex:none;
701:     width:88px;height:88px;border-radius:50%;
702:     background:rgba(255,255,255,.14);border:2px solid rgba(255,255,255,.65);
703:     font-family:var(--fonte-titulo);font-size:34px;font-weight:700;
704: }
705: .profile-hero-info{min-width:0;flex:1}
706: .profile-hero-info h2{font-family:var(--fonte-titulo);font-size:26px;line-height:1.2;margin:0 0 4px;letter-spacing:-.015em}
707: .profile-hero-info p{margin:0 0 10px;color:#c9cfd7;font-size:14.5px}
708: .profile-hero-meta{display:flex;gap:8px;flex-wrap:wrap;align-items:center}
709: .profile-hero-meta .chip{background:rgba(255,255,255,.14);color:#fff}
710: .profile-hero-meta .chip::before{background:#ffc247}
711: .profile-hero-meta .status{background:rgba(255,255,255,.14);color:#c9f0dc}
712: .profile-hero-actions{margin-left:auto;display:flex;gap:10px;flex-wrap:wrap}
713: .profile-hero .botao-sec{background:rgba(255,255,255,.1);border-color:rgba(255,255,255,.4);color:#fff}
714: .profile-hero .botao-sec:hover{background:rgba(255,255,255,.2);border-color:#fff;color:#fff}
715: 
716: .info-grid{display:grid;gap:14px;grid-template-columns:repeat(auto-fit,minmax(220px,1fr))}
717: .info-item{
718:     display:flex;align-items:flex-start;gap:12px;
719:     padding:14px 15px;border:1px solid var(--linha);border-radius:var(--raio-sm);background:#fbfcfd;
720: }
721: .info-item .stat-icon{width:34px;height:34px;border-radius:8px}
722: .info-item dt{font-size:11.5px;font-weight:700;letter-spacing:.05em;text-transform:uppercase;color:var(--suave-2)}
