432:     $_SESSION['usuario_perfil'] = $perfil;
433:     $_SESSION['usuario_funcao'] = $u['funcao'] ?? $perfil;
434:     $_SESSION['perfil']         = $perfil;
435:     $_SESSION['ultimo_login']   = $u['ultimo_acesso'] ?? null;
436: 
